QGraphicsItem *dimensionTextItem(DrawingSheetEditor &e,QUuid id,const char *kind="dimension"){
 for(auto *item:e.canvas()->scene()->items())if(item->data(0).toString()==kind&&item->data(3).toUuid()==id)return item;
 throw std::runtime_error("elemento testo quota assente");
}
